-- AnyBike seven exact source-backed model intake — private draft only.
-- Canonical ID, unchanged staging, pending alias and publication guards.
DO $$
DECLARE eligible integer; inserted integer; before_pub integer; after_pub integer;
BEGIN
 SELECT count(*) INTO before_pub FROM public.motorcycle_universal_published_sections_v1;
 WITH expected(id,make,model) AS (VALUES (224,'Royal Enfield','Classic 500 Tribute Black'),
 (664,'Triumph','Daytona 660'),
 (677,'Triumph','Tiger Sport 660'),
 (259,'Triumph','Tiger Sport 800'),
 (666,'Triumph','Rocket 3'),
 (241,'Triumph','ROCKET III'),
 (881,'KTM','RC 125'))
 SELECT count(*) INTO eligible FROM expected x
 JOIN public.motorcycle_catalog_models m ON m.id=x.id AND m.manufacturer=x.make AND m.model=x.model
 WHERE NOT EXISTS(SELECT 1 FROM public.motorcycle_universal_page_sections_v1 s WHERE s.entity_type='model' AND s.model_id=x.id)
 AND NOT EXISTS(SELECT 1 FROM public.motorcycle_catalog_model_aliases a WHERE a.alias_model_id=x.id AND a.review_status<>'approved')
 AND EXISTS(SELECT 1 FROM public.motorcycle_catalog_manufacturers r WHERE r.display_name=x.make);
 IF eligible<>7 THEN RAISE EXCEPTION 'Identity or staging changed: expected seven, got %',eligible; END IF;
 INSERT INTO public.motorcycle_universal_page_sections_v1
 (entity_type,manufacturer_id,model_id,section_number,section_title,content,editorial_status,source_reference,published_at)
 SELECT 'model',NULL,v.model_id,v.section_number,v.section_title,v.content,'draft',
 'official_model_heritage_2026_11_10:'||v.source_url,NULL
 FROM (VALUES (224,1,'Model introduction','{"summary":"The Classic 500 Tribute Black was a limited-edition Royal Enfield single-cylinder motorcycle commemorating the end of India''s 500 cc UCE model production.","source_name":"Royal Enfield manufacturer document","source_url":"https://www.royalenfield.com/in/en/our-world/media/press-releases/product-launches/royal-enfield-launches-the-classic-500-tribute-black/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/press-releases/product-launches/royal-enfield-launches-the-classic-500-tribute-black/'),
 (224,7,'Documented chronology','{"summary":"Royal Enfield announced the Tribute Black on 31 January 2020 and scheduled an India-only online sale for 10 February 2020.","source_name":"Royal Enfield manufacturer document","source_url":"https://www.royalenfield.com/in/en/our-world/media/press-releases/product-launches/royal-enfield-launches-the-classic-500-tribute-black/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/press-releases/product-launches/royal-enfield-launches-the-classic-500-tribute-black/'),
 (224,13,'Edition identification','{"summary":"Royal Enfield specifies a numbered End of Build plaque for each example; the edition is not identical to an ordinary Classic 500 or to the later Classic 350.","source_name":"Royal Enfield manufacturer document","source_url":"https://www.royalenfield.com/in/en/our-world/media/press-releases/product-launches/royal-enfield-launches-the-classic-500-tribute-black/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/press-releases/product-launches/royal-enfield-launches-the-classic-500-tribute-black/'),
 (664,1,'Model introduction','{"summary":"The Daytona 660 is Triumph''s road-oriented three-cylinder sports motorcycle based on the manufacturer''s modern 660 platform.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/daytona-660-q-and-a-2024-04-25?sc_camp=2CBCBF4299F645E4874CCF3EA9776CA4","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/daytona-660-q-and-a-2024-04-25?sc_camp=2CBCBF4299F645E4874CCF3EA9776CA4'),
 (664,7,'Documented launch-era history','{"summary":"Triumph''s April 2024 Daytona 660 Q&A presents the model as a new road-focused sports machine with a distinct frame and reworked triple engine relative to the Trident 660.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/daytona-660-q-and-a-2024-04-25?sc_camp=2CBCBF4299F645E4874CCF3EA9776CA4","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/daytona-660-q-and-a-2024-04-25?sc_camp=2CBCBF4299F645E4874CCF3EA9776CA4'),
 (664,12,'2024 factory technical evidence','{"summary":"Triumph quotes 95 PS maximum output, 69 Nm torque and 201 kg wet weight for the launch-era Daytona 660; Shift Assist is identified as an accessory, not standard equipment.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/daytona-660-q-and-a-2024-04-25?sc_camp=2CBCBF4299F645E4874CCF3EA9776CA4","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/daytona-660-q-and-a-2024-04-25?sc_camp=2CBCBF4299F645E4874CCF3EA9776CA4'),
 (677,1,'Model introduction','{"summary":"The Tiger Sport 660 is Triumph''s middleweight triple-cylinder sport-tourer for commuting and longer road journeys.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/tiger-sport-660-2024-11-19","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/tiger-sport-660-2024-11-19'),
 (677,7,'Documented model-year update','{"summary":"Triumph announced a revised Tiger Sport 660 on 19 November 2024, with rider-focused technology and touring changes. That announcement does not define every earlier Tiger Sport 660.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/tiger-sport-660-2024-11-19","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/tiger-sport-660-2024-11-19'),
 (677,13,'Design and riding character','{"summary":"Triumph''s model-year announcement emphasises urban use, passenger comfort and weekend touring, distinguishing this road-based Tiger Sport from the Tiger off-road-adventure lines.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/tiger-sport-660-2024-11-19","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/tiger-sport-660-2024-11-19'),
 (259,1,'Model introduction','{"summary":"The Tiger Sport 800 extends Triumph''s sport-touring road range beyond the Tiger Sport 660 with additional capacity and longer-distance focus.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/adventure/tiger-sport-800-dealer-tour","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/adventure/tiger-sport-800-dealer-tour'),
 (259,7,'Documented UK preview','{"summary":"Triumph publicised a UK dealer preview tour for the new Tiger Sport 800 running from December 2024 to early March 2025. Preview dates do not establish all market sales dates.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/adventure/tiger-sport-800-dealer-tour","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/adventure/tiger-sport-800-dealer-tour'),
 (259,13,'Documented character','{"summary":"Triumph positions the model as balancing sporting performance with long-distance road comfort. The later Tiger Sport 800 Tour is a distinct higher-equipment variant.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/adventure/tiger-sport-800-dealer-tour","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/adventure/tiger-sport-800-dealer-tour'),
 (666,1,'Model introduction','{"summary":"Triumph''s modern Rocket 3 is a high-capacity triple-cylinder road motorcycle, succeeding the earlier Rocket III family.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/the-storm-is-coming-2024-03-28","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/the-storm-is-coming-2024-03-28'),
 (666,7,'Documented model evolution','{"summary":"Triumph''s March 2024 article introduced the Rocket 3 Storm R and GT as a newly revised generation, around twenty years after the original Rocket III.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/the-storm-is-coming-2024-03-28","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/the-storm-is-coming-2024-03-28'),
 (666,12,'2024 Storm-specific engineering','{"summary":"For the Rocket 3 Storm models, Triumph quotes 2,458 cc displacement, 182 PS maximum power and 225 Nm torque. These figures must not be assigned to older Rocket 3 or Rocket III versions.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/the-storm-is-coming-2024-03-28","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/the-storm-is-coming-2024-03-28'),
 (241,1,'Model introduction','{"summary":"The original Rocket III established Triumph''s distinctive large-displacement three-cylinder cruiser family, preceding the later Rocket 3 generations.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/the-storm-is-coming-2024-03-28","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/the-storm-is-coming-2024-03-28'),
 (241,7,'Historical identity','{"summary":"Triumph''s March 2024 retrospective places the first Rocket III roughly twenty years earlier. It contrasts the original motorcycle with the newer Rocket 3 Storm.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/the-storm-is-coming-2024-03-28","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/the-storm-is-coming-2024-03-28'),
 (241,13,'Distinct generation guidance','{"summary":"The original Rocket III must retain a separate canonical identity from the newer Rocket 3, Rocket 3 TFC and Storm editions; the 2024 Storm figures are not original Rocket III specifications.","source_name":"Triumph manufacturer document","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/the-storm-is-coming-2024-03-28","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/the-storm-is-coming-2024-03-28'),
 (881,1,'Model introduction','{"summary":"The RC 125 is KTM''s learner-oriented small-capacity fully faired road sports motorcycle, distinct from the larger RC 390.","source_name":"KTM manufacturer document","source_url":"https://press.ktm.com/news-ktm-announces-new-vat-free-power-deals-ktm-sportmotorcycle-uk?id=204298&imageid=802238&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://press.ktm.com/news-ktm-announces-new-vat-free-power-deals-ktm-sportmotorcycle-uk?id=204298&imageid=802238&l=uk&menueid=5904'),
 (881,7,'Documented UK model year','{"summary":"KTM''s September 2024 UK model-year listing includes the RC 125 for MY24. It is evidence of that model''s UK range presence, not a first-generation launch date.","source_name":"KTM manufacturer document","source_url":"https://press.ktm.com/news-ktm-announces-new-vat-free-power-deals-ktm-sportmotorcycle-uk?id=204298&imageid=802238&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://press.ktm.com/news-ktm-announces-new-vat-free-power-deals-ktm-sportmotorcycle-uk?id=204298&imageid=802238&l=uk&menueid=5904'),
 (881,12,'Model-specific evidence limits','{"summary":"The published KTM UK material identifies the RC 125 separately from the RC 390; contemporary promotion prices and finance terms must not be treated as permanent factory specifications.","source_name":"KTM manufacturer document","source_url":"https://press.ktm.com/news-ktm-announces-new-vat-free-power-deals-ktm-sportmotorcycle-uk?id=204298&imageid=802238&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Primary source independently located; claim-level editorial check, exact market/year and image rights still required."}'::jsonb,'https://press.ktm.com/news-ktm-announces-new-vat-free-power-deals-ktm-sportmotorcycle-uk?id=204298&imageid=802238&l=uk&menueid=5904')) v(model_id,section_number,section_title,content,source_url);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>21 THEN RAISE EXCEPTION 'Expected 21 private sections; inserted %',inserted; END IF;
 SELECT count(*) INTO after_pub FROM public.motorcycle_universal_published_sections_v1;
 IF before_pub<>after_pub THEN RAISE EXCEPTION 'Public projection unexpectedly changed'; END IF;
END $$;
